code.cpp:
class Solution {
public:
    int distributeCandies(vector<int>& candyType) {
        unordered_set<int> distinct(candyType.begin(), candyType.end());
        int types = (int)distinct.size();
        int limit = (int)candyType.size() / 2;
        return min(types, limit);
    }
};
